"""Qa tool schemas and native operation declarations."""

from ..qa_flow_schema import (
    DECLARED_MACHINE_FLOWS_SCHEMA,
)
from ..qa_tasks import (
    QA_ORIGIN_SCHEMA,
)
from .common import (
    EXPECTED_WORLD,
    LIVE_ID,
    QUERY,
    ToolSpec,
    integer,
    obj,
)


QA_CATALOG_SCHEMA = {**obj({"section": {"type": "string", "enum": ["tests", "selectors", "templates", "diagnostics", "capabilities", "fixture_plan", "flow_evidence", "machines", "recipe_maps"]},
    "query": QUERY, "offset": integer(0, 100000), "limit": integer(1, 64), "origin": QA_ORIGIN_SCHEMA, "machineFlows": DECLARED_MACHINE_FLOWS_SCHEMA}),
    "allOf": [{"if": {"required": ["origin"]}, "then": {"required": ["section"], "properties": {"section": {"const": "fixture_plan"}}}},
        {"if": {"required": ["machineFlows"]}, "then": {"required": ["section", "query"], "properties": {
            "section": {"enum": ["tests", "diagnostics", "fixture_plan", "flow_evidence"]}, "query": {"const": "tstqa:DeclaredMachineFlow.run"}}}}]}


QA_RUN_SCHEMA = {**obj({"selector": {"type": "string", "minLength": 1, "maxLength": 256}, "expectedWorld": EXPECTED_WORLD,
    "origin": QA_ORIGIN_SCHEMA, "machineFlows": DECLARED_MACHINE_FLOWS_SCHEMA}, ["expectedWorld"]),
    "if": {"required": ["machineFlows"]}, "then": {"required": ["selector"], "properties": {"selector": {"const": "tstqa:DeclaredMachineFlow.run"}}}}


QA_COMMAND_SCHEMA = {**obj({"command": {"type": "string", "enum": ["run", "runall", "runfailed", "tp", "runthis", "runthat", "pos", "clearall", "load", "export", "clear", "label", "labels", "forget"]}, "args": {"type": "array", "items": {"type": "string", "minLength": 1, "maxLength": 256, "pattern": r"^[^\x00-\x20\x7F]+$"}, "maxItems": 8}, "expectedWorld": EXPECTED_WORLD}, ["command", "expectedWorld"]), "allOf": [{
    "if": {"properties": {"command": {"enum": ["forget", "clear"]}}, "required": ["command"]},
    "then": {"required": ["args"], "properties": {"args": {"minItems": 1, "maxItems": 1,
        "items": {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"}}}},
}]}


T_MCB_QA_CATALOG = ToolSpec("mcb_qa_catalog", "qa.catalog", "Discover installed public QA capabilities, tests and diagnostics as a bounded page. Dimension 0 uses native HQA; a verified PersonalDimension uses the TST-QA public-instance runner in the actual world/provider/session. fixture_plan requires one exact ID and reports its actual public template bounds. Optional complete origin={x,y,z} is accepted only with section=fixture_plan and selects the private public-instance allocation; native HQA does not support this override. flow_evidence reads one exact case, including active infinite observationReady and quantified output evidence when available. section defaults tests, query filters entries, limit max64. Capabilities discovery is available in every policy, including a server without QA. Other reads require observe or a proved owned run. Requires an owned integrated developer context or a connected server with the same MCB, QA and operator-level-2 permission. Missing public API is explicitly unavailable. The private TST-QA adapter additionally accepts immutable machineFlows (1..10) with query=tstqa:DeclaredMachineFlow.run for tests/diagnostics/fixture_plan/flow_evidence. machines and recipe_maps page public registered prototypes/NEI maps only; their default prototype state is not a placed or formed machine. Native dimension 0 cannot execute declarations. No screenshot or test launch.", QA_CATALOG_SCHEMA, True)


T_MCB_QA_RUN = ToolSpec("mcb_qa_run", "qa.run", "Creative test policy accepts only reviewed finite callbacks/declarations advertised by the private runner; unreviewed/native-global runs require manage. Start one public QA run in the exact expected developer world (local or an authenticated server). Dimension 0 retains native HQA reported-run tickets and unverified native-global ownership. A verified PersonalDimension uses the TST-QA public-instance lifecycle in its actual WorldServer; inspect the real dimension/provider/session and UUID. Optional origin={x,y,z} selects the public private-instance allocation origin; all three bounded integer coordinates are required. Actual server reserve, loaded-world and ground guards remain mandatory. Returns a start receipt, never proof of successful tests. Private TST-QA declared flows use selector=tstqa:DeclaredMachineFlow.run and machineFlows with exact live item identities, complete public recipe declarations (deterministic by default), an exact actual voltageTier <= assumedVoltageTier (default: actual tier) and optional native inventory upgrades. Declared multiblock raw item counts and durationTicks use the public signed-int range; complete actual slot/tank capacity and exact native recipe matching remain mandatory. BasicMachine and upgrade manufacturing declarations retain counts <=64, duration <=3500 and distinct raw identities. Explicit ordinary finite multiblocks additionally accept recipe.outputChances: one original integer 0..10000 per raw item output, length exactly matching outputs; omission means 10000. Chance0 and zero results are legal only with real single completion and consumed inputs. Maximum raw potential plus catalysts must fit. Schema2/tstqa-finite-item-chances-v1 separately binds raw potential/chance, deep-copied normal-END native pending, actual full deposit, actual+catalyst recovery and 85 stopped ticks; missed pending is unknown and cannot pass required full generation-to-deposit proof. Single execution never proves a probability distribution and is never rerolled. BasicMachine, automatic selection and upgrade manufacturing retain deterministic output chances. Input/fluid chances, multiple fluids and unrepresented special/metadata rules remain unsupported. expectedRemainingCount=0/1 declares native consumption/retention (default 1); waitTicks=1..400 defaults 100 and advances only normal world ticks. Exact newly observed expectedFeedbackLines or whitelisted publicFeedback.getMaxParallelRecipes={formed:N,before?:N,after?:N} is mandatory. Missing pre-formation comparisons remain unknown; consumed inventory alone never proves upgrade success. The same upgraded controller is reused for native blueprint construction, exact energy hatch formation, public formed getter feedback, finite products/recovery and stopped stability. Direct GT manufacturing recipes must fit the assumed cap. manufacturingRecipe={source:public_crafting,outputCount:N} requires exact actual registered output and complete supported vanilla/Forge public ingredients with bounded normal IRecipe.matches on a temporary memory grid in the actual server world; crafting directEUt is not_applicable, unknown custom/NBT/wildcard/ore rules stay unsupported. Manufacturing is eligibility verification, not actual manufacture or recursive ingredient/structure-material progression proof. Unknown rules are unsupported; no substitute recipe, overvoltage, downgrade, private writes or per-machine case adaptation. Inspect immutable declarations/digests, fixtures and actual run evidence via catalog/status/results. mcb_qa_test_once accepts one fixed case or 1..10 immutable machineFlows and verifies every same-run fixture and full flow. Refuses overlapping runs and is never automatically retried. Infinite cases can remain active with observationReady evidence; inspect status/results before requesting a normal stop with mcb_qa_cancel.", QA_RUN_SCHEMA)


T_MCB_QA_STATUS = ToolSpec("mcb_qa_status", "qa.status", "Read public QA run activity and same-run evidence. Dimension 0 reports native HQA global activity with unverified completion ownership. The private public-instance route binds the actual WorldServer/provider/session and owned adapter UUID while native-global ownership stays false. Infinite observationReady and quantified production may be returned while the run remains active; this does not prove finite PASS or stopped stability. Optional waitMillis0..8000 is a bounded same-run read wait only when fresh private capabilities advertise boundedStatusWait; positive waits require runId and never block normal world ticks. Timeout returns actual current status and is not completion evidence. No action, cancellation or screenshot.", {**obj({"runId": LIVE_ID, "waitMillis": integer(0, 8000)}), "if": {"required": ["waitMillis"], "properties": {"waitMillis": {"minimum": 1}}}, "then": {"required": ["runId"]}}, True)


T_MCB_QA_RESULTS = ToolSpec("mcb_qa_results", "qa.results", "Read a bounded page of public QA cases or infrastructure issues; limit max32. includeDetails defaults false; request true for bounded output/trace diagnostics and inspect detailsCoverage. runId binds the world/session and freshness baseline; private adapter results also retain actual dimension/provider and adapter UUID. Native-global ownership remains unverified. Active infinite evidence can report actual output increments before completion; do not infer PASS or stopped stability. Never read arbitrary report paths or infer success from prior runs.", obj({"runId": LIVE_ID, "section": {"type": "string", "enum": ["cases", "issues"]}, "offset": integer(0, 100_000), "limit": integer(1, 32), "includeDetails": {"type": "boolean", "default": False}}), True)


T_MCB_QA_COMMAND = ToolSpec("mcb_qa_command", "qa.command", "Invoke one existing public QA command with a bounded argument vector in the exact expected developer world (local or an authenticated server). Dimension 0 retains native HQA command validation and reported-run tickets. In a verified PersonalDimension, run requires one exact test ID and uses the TST-QA public-instance runner; unsupported native commands remain unavailable. Private clear and forget require args=[canonical UUID runId] for one completed run in this exact world/session; clear removes only unchanged owned fixture blocks; forget releases only bounded cached history and chunk leases while retaining blocks. Both require a completed run. Native dimension 0 rejects per-run clear/forget because it cannot prove fixture ownership. Private clearall uses the latest completed owned adapter run in the actual world/session and requires its unchanged owned fixture. Infinite runs expose active observations through status/evidence and use mcb_qa_cancel for normal stop/drain. Management-level native load/clearall mutate test regions; export uses HQA's own path. No shell command, private field access, mouse or automatic retry.", QA_COMMAND_SCHEMA)


T_MCB_QA_CANCEL = ToolSpec("mcb_qa_cancel", "qa.cancel", "Request a normal stop of an explicitly identified owned TST-QA public-instance run in the verified PersonalDimension and expected local or authenticated server world. Infinite runs stop supply and continue normal drain, recovery and real stopped stability; a requested_stop receipt proves neither completion nor PASS. HQA0.15 native-global runs have no public per-run cancellation API and remain unavailable. Inspect the same runId with status/results. No global shutdown, foreign-run stop or automatic retry.", obj({"runId": LIVE_ID, "expectedWorld": EXPECTED_WORLD}, ["runId", "expectedWorld"]))
